#!/bin/bash
# Uninstall script for Eclipse for RCP and RAP Developers
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Eclipse for RCP and RAP Developers..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Eclipse for RCP and RAP Developers if running..."
pkill -f "Eclipse for RCP and RAP Developers" 2>/dev/null || true

# Remove /Applications/Eclipse.app
echo "Removing /Applications/Eclipse.app..."
if [ -d "/Applications/Eclipse.app" ]; then
    rm -rf "/Applications/Eclipse.app" 2>/dev/null || true
elif [ -f "/Applications/Eclipse.app" ]; then
    rm -f "/Applications/Eclipse.app" 2>/dev/null || true
fi

# Remove /Applications/{'target': 'Eclipse RCP.app'}
echo "Removing /Applications/{'target': 'Eclipse RCP.app'}..."
if [ -d "/Applications/{'target': 'Eclipse RCP.app'}" ]; then
    rm -rf "/Applications/{'target': 'Eclipse RCP.app'}" 2>/dev/null || true
elif [ -f "/Applications/{'target': 'Eclipse RCP.app'}" ]; then
    rm -f "/Applications/{'target': 'Eclipse RCP.app'}" 2>/dev/null || true
fi

# Remove $HOME/.eclipse
echo "Removing $HOME/.eclipse..."
if [ -d "$HOME/.eclipse" ]; then
    rm -rf "$HOME/.eclipse" 2>/dev/null || true
elif [ -f "$HOME/.eclipse" ]; then
    rm -f "$HOME/.eclipse" 2>/dev/null || true
fi

# Remove $HOME/eclipse-workspace
echo "Removing $HOME/eclipse-workspace..."
if [ -d "$HOME/eclipse-workspace" ]; then
    rm -rf "$HOME/eclipse-workspace" 2>/dev/null || true
elif [ -f "$HOME/eclipse-workspace" ]; then
    rm -f "$HOME/eclipse-workspace" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/epp.package.rcp.plist
echo "Removing $HOME/Library/Preferences/epp.package.rcp.plist..."
if [ -d "$HOME/Library/Preferences/epp.package.rcp.plist" ]; then
    rm -rf "$HOME/Library/Preferences/epp.package.rcp.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/epp.package.rcp.plist" ]; then
    rm -f "$HOME/Library/Preferences/epp.package.rcp.plist" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
